// The content files the app ships instead of asking the graph (src/data/content/, generated by
// scripts/content-snapshot/build.mjs from a --content-only export; refreshed by load-graph.mjs).
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { assertContentOnly, buildParts, buildRelatedWords, buildSnapshots, indexGraph, USER_LABELS } from "../scripts/content-snapshot/build.mjs";
import { isLocalUri } from "../scripts/load-graph.mjs";
import { partsFromFixture } from "./lib/partsContentFixture.mjs";
import { PARTS_FIELDS, PARTS_KEYS } from "../scripts/content-snapshot/partsAllowlist.mjs";

const shipped = (name) => JSON.parse(readFileSync(`src/data/content/${name}`, "utf8"));
const node = (id, labels, props = {}) => ({ elementId: id, labels, props: { id, ...props } });
const rel = (type, start, end, props = {}) => ({ elementId: `${type}:${start}:${end}`, type, start, end, props });

test("build refuses anything but a content-only export with no user data", () => {
  const base = { scope: "content-only", nodes: [node("calm", ["Emotion"])], relationships: [] };
  assert.doesNotThrow(() => assertContentOnly(base));
  assert.throws(() => assertContentOnly({ ...base, scope: "no-profile" }), /--content-only/);
  assert.throws(() => assertContentOnly({ ...base, scope: "all" }), /--content-only/);
  for (const label of USER_LABELS) {
    assert.throws(() => assertContentOnly({ ...base, nodes: [...base.nodes, node("x", [label])] }), /user-data/, label);
  }
  assert.throws(() => assertContentOnly({ ...base, relationships: [rel("RELATED_TO", "calm", "gone")] }), /doesn't contain/);
  assert.throws(() => buildSnapshots({ ...base, nodes: [node("u", ["CheckIn", "UserData", "LogRecord"])] }), /user-data/);
});

test("related words keep RELATED_TO and shared-brain rows, never OPPOSITE_OF", () => {
  const nodes = [
    node("calm", ["Emotion"], { name: "Calm", quadrant: "low-pleasant" }),
    node("happy", ["Emotion"], { name: "Happy", quadrant: "high-pleasant" }),
    node("sad", ["Emotion"], { name: "Sad", quadrant: "low-unpleasant" }),
    node("tired", ["Emotion"], { name: "Tired", quadrant: "low-unpleasant" }),
    node("insula", ["BrainStructure"]),
  ];
  const relationships = [
    rel("RELATED_TO", "happy", "calm"),
    rel("OPPOSITE_OF", "calm", "sad"),
    rel("ACTIVATES_DURING", "insula", "calm"),
    rel("ACTIVATES_DURING", "insula", "tired"),
  ];
  const byId = new Map(nodes.map((n) => [n.elementId, n]));
  const g = {
    nodes: (l) => nodes.filter((n) => n.labels.includes(l)),
    rels: (t, a, b) => relationships.filter((r) => r.type === t)
      .map((r) => ({ props: r.props, a: byId.get(r.start), b: byId.get(r.end) }))
      .filter((r) => (!a || r.a.labels.includes(a)) && (!b || r.b.labels.includes(b))),
  };
  const out = buildRelatedWords(g);
  assert.deepEqual(out.calm.map((r) => [r.id, r.reason]), [["happy", "related feeling"], ["tired", "related feeling"]]);
  assert.equal(out.calm[0].quadrant, "high-pleasant");
  assert.ok(!JSON.stringify(out).includes("opposite"));
});

test("shipped files carry their source, and related words has no opposites and covers every grid word", () => {
  for (const name of ["related-words.json", "body-map.json", "find-the-feeling.json", "discriminating-questions.json", "capacity.json", "spine.json", "parts.json", "wise-mind.json"]) {
    const f = shipped(name);
    assert.match(f.source.file, /^graph-content-only-.*\.json$/, name);
    assert.ok(!Number.isNaN(Date.parse(f.source.exportedAt)), name);
    assert.ok(f.content, name);
  }
  const related = shipped("related-words.json").content;
  for (const [id, rows] of Object.entries(related)) {
    for (const r of rows) assert.notEqual(r.reason, "opposite emotion", `${id} → ${r.id}`);
  }
  const grid = [...readFileSync("src/data/emotions.ts", "utf8").matchAll(/makeEmotion\('([a-z_]+)'/g)].map((m) => m[1]);
  const missing = grid.filter((id) => !related[id]?.length);
  assert.deepEqual(missing, [], "grid words with nothing in the graph to relate them to");
});

// Drift guards: the shipped files (from the live graph) against the fixtures (from content.py).
// A failure here means content.py changed without a graph load: load it, and load-graph.mjs
// refreshes src/data/content/ (or run `npm run content:refresh`).
test("shipped Find the feeling content matches content.py", () => {
  assert.deepEqual(shipped("find-the-feeling.json").content, JSON.parse(readFileSync("tests/fixtures/find-the-feeling-content.json", "utf8")));
});

test("shipped body map content matches content.py", () => {
  const snap = shipped("body-map.json").content;
  const fix = JSON.parse(readFileSync("tests/fixtures/body-map-content.json", "utf8"));
  const strip = (o, keys) => Object.fromEntries(Object.entries(o).filter(([k]) => !keys.includes(k)));
  assert.equal(snap.version, fix.version);
  assert.deepEqual(snap.regions, fix.regions);
  assert.deepEqual(snap.padWords, fix.padWords.filter((p) => (p.status ?? "live") === "live").map((p) => strip(p, ["status"])));
  const live = fix.maps.filter((m) => (m.status ?? "live") === "live");
  assert.deepEqual(snap.maps.map((m) => m.id).sort(), live.map((m) => m.id).sort());
  for (const m of snap.maps) {
    const f = live.find((x) => x.id === m.id);
    assert.equal(m.label, f.label, m.id);
    assert.deepEqual(m.wordIds, f.wordIds, m.id);
    assert.deepEqual(m.places, f.places.filter((p) => (p.status ?? "live") === "live").map((p) => strip(p, ["status", "emotionIds"])), m.id);
  }
});

test("shipped follow-up questions: both unpleasant quadrants, no clinical notes, follow-ups resolve, match the schema", () => {
  const shippedQs = shipped("discriminating-questions.json").content;
  const fixture = JSON.parse(readFileSync("tests/fixtures/recommendation-graph.json", "utf8"));
  // The check-in asks them for both unpleasant quadrants (CheckIn.tsx asksDiscriminatingQuestions).
  for (const q of ["high-unpleasant", "low-unpleasant"]) assert.ok(shippedQs[q]?.length > 0, q);
  // Only what getDiscriminatingQuestions returns: never the rationale, citations or signals.
  const text = JSON.stringify(shippedQs);
  for (const field of ["clinicalRationale", "keyCitations", "clinicalSignal", "clinicalDimension"]) assert.ok(!text.includes(field), field);
  for (const [quadrant, qs] of Object.entries(shippedQs)) {
    const ids = new Set(qs.map((q) => q.id));
    for (const q of qs) {
      assert.ok(q.text && q.responses.length > 0, q.id);
      for (const r of q.responses) if (r.triggersNextQuestionId) assert.ok(ids.has(r.triggersNextQuestionId), `${q.id} → ${r.triggersNextQuestionId}`);
    }
    // Drift guard: the same questions, in the same order, as the schema files say.
    assert.deepEqual(qs.map((q) => q.id), fixture.questions[quadrant] ?? [], quadrant);
  }
  // Every answer the engine scores (EVIDENCE_FOR) is one the app can send.
  const responseIds = new Set(Object.values(shippedQs).flat().flatMap((q) => q.responses.map((r) => r.id)));
  const scored = [...new Set(fixture.evidence.map((e) => e.responseId))];
  assert.deepEqual(scored.filter((id) => !responseIds.has(id)), []);
});

